    [9, 9, 9, 9, 9, 9, 9, 9, 4, 9, 9, 9, 9, 9, 9, 9, 9, 4, 9, 9, 9, 9, 9, 9, 9, 9],
    [9, 9, 9, 9, 9, 9, 9, 9, 4, 9, 9, 9, 9, 9, 9, 9, 9, 4, 9, 9, 9, 9, 9, 9, 9, 9],
    [4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4],
    [9, 9, 9, 9, 9, 9, 9, 9, 4, 8, 9, 8, 9, 6, 9, 8, 7, 4, 9, 9, 9, 9, 9, 9, 9, 9],
    [9, 9, 9, 9, 9, 9, 9, 9, 4, 9, 9, 9, 8, 8, 3, 9, 9, 4, 9, 9, 9, 9, 9, 9, 9, 9]
]

END_DIV = 2  # Horizontal divider row
COL1_DIV = 8  # First vertical divider col
COL2_DIV = 17  # Second vertical divider col

def flip_coords(r, c):
    """Flip coordinates around dividers to get all quadrants"""
    results = []
    vertical_flips = [c, 2*(COL1_DIV) - c, 2*(COL2_DIV) - c]
    for r_flip in [r, 2*END_DIV - r]:
        for c_flip in vertical_flips:
            # Skip divider positions
            if c_flip in [COL1_DIV, COL2_DIV]:
                continue
            results.append((r_flip, c_flip))
    return list(set(results))

# Build output
output = [[9]*26 for _ in range(10)]
for r in range(5):
    for c in range(26):
        val = input_grid[r][c]
        if val != 9:  # Only mirror non-background
            for (or_, oc) in flip_coords(r, c):
                output[or_][oc] = val

# Also include the horizontal flip of the pattern for symmetry
for r in range(10):
    for c in range(26):
        # Mirror output itself around vertical dividers
        for c_flip in [2*COL1_DIV - c, 2*COL2_DIV - c]:
            if c_flip < 26:
                if output[r][c_flip] == 9 and output[r][c] != 9:
                    output[r][c_flip] = output[r][c]

print("Final output:")
for row in output:
    print(" ".join(map(str, row)))
print("\nJSON:", json.dumps({"action": "submit", "grid": output}))

